import {mountTheses} from './thesis.js';
import {mountResearchDelivery} from './catalyst-delivery.js';
import {mountFreeResearch} from './catalyst-chat.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={KR_STOCK:'국내 주식',US_STOCK:'미국 주식',CRYPTO:'코인',FORWARD_IMPACT:'사건 → 영향 경로',MOVE_ANALYSIS:'가격 움직임 → 촉매',RELATED_ASSET_SEARCH:'관련 자산 탐색',CROSS_ASSET_ANALYSIS:'시장 간 연결',queued:'분석 대기',identity:'자산 확인',market:'시세 기준 확인',evidence:'공시·뉴스 원문 확인',analyzing:'촉매 구조화',validating:'인용·전달경로 검증',VERIFIED:'공식 원문 확인',SUPPORTED:'복수 근거',INFERRED:'추론 · 추가 확인 필요',UNVERIFIED:'미확인',CONFLICTED:'자료 충돌',RUMOR:'루머',HIGH:'높음',MEDIUM:'보통',LOW:'낮음',positive:'긍정 경로',negative:'부정 경로',unclear:'방향 미확인',event:'사건',business:'사업 내용',transmission:'전달 경로',value_capture:'토큰 가치 귀속',customer:'고객·공급 관계',protocol_metric:'프로토콜 지표',tokenomics:'토큰 구조',revenue_share:'매출 비중',attribution:'가격 움직임의 배경',SAME_CATALYST:'같은 촉매',SECOND_ORDER:'간접 전달',SAME_NARRATIVE:'같은 이야기 · 경로 미확인',SAME_ECOSYSTEM:'같은 생태계',TOKENOMICS_SIMILAR:'유사 토큰 구조'};
const time=s=>!s?'시각 미확인':/^\d{4}-\d{2}-\d{2}$/.test(s)?s+' · 일자 기준':Number.isFinite(Date.parse(s))?new Intl.DateTimeFormat('ko-KR',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Seoul'}).format(new Date(s))+' KST':'시각 미확인';
const num=(n,suffix='',sign=false)=>Number.isFinite(n)?(sign&&n>0?'+':'')+n.toLocaleString('ko-KR',{maximumFractionDigits:2})+suffix:'미확인';
const external=(url,text)=>typeof url==='string'&&/^https:\/\//.test(url)?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(text)} ↗</a>`:esc(text);
const examples=['AI 데이터센터 투자가 늘어나면?','MU 주가가 오른 이유는?','이더리움과 관련된 코인은?','미국 메모리 수요가 국내 기업에 전달되는 경로는?'];
function claimMarkup(c){return `<article class="cf-claim"><div class="cf-meta"><span class="cf-badge">${esc(labels[c.type]||c.type)}</span><span>${esc(labels[c.status]||c.status)}</span></div><blockquote>${esc(c.quote)}</blockquote><p class="cf-meta">${external(c.sourceUrl,'원문 확인')} · ${c.asOfKind==='observed'?'문서 확인 ':''}${esc(time(c.asOf))}</p>${c.locator?`<p class="cf-meta">${esc(c.locator)}</p>`:''}${c.reasons?.length?`<p class="cf-warning">${esc(c.reasons.join(' · '))}</p>`:''}</article>`;}
function candidateMarkup(c,claims){return `<article class="surface cf-candidate"><header><div><span class="cf-badge">${esc(labels[c.asset.kind])}</span><h3><a href="${esc(c.asset.href)}" data-nav>${esc(c.asset.name)} <small>${esc(c.asset.symbol)}</small></a></h3></div><span>${esc(labels[c.direction])}</span></header><p><strong>${esc(c.product)}</strong> · ${esc(labels[c.relationship])}</p><p>${esc(c.explanation)}</p><ol class="cf-path">${(c.path||[]).map(p=>`<li><span>${esc(p.from)}</span><b aria-label="전달 방향">→</b><span>${esc(p.to)}</span></li>`).join('')}</ol><details><summary>근거·신뢰도 확인</summary><p>근거 신뢰도 ${esc(labels[c.score.confidence])} · 추가 자료 충족 ${c.score.coverage}%</p><p>${c.score.score===null?'점수 보류 · '+esc(c.score.band):'영향 경로 점수 '+c.score.score+' / 100'} <small>${esc(c.score.version)}</small></p>${claims.filter(x=>c.claimIds.includes(x.id)).map(claimMarkup).join('')||'<p>검증을 통과한 연결 근거가 없습니다.</p>'}</details></article>`;}
function marketMarkup(m){if(!m)return '';return `<section class="surface cf-market"><header><h2>가격 움직임</h2><strong>${num(m.price)} ${esc(m.currency)}</strong></header><p class="cf-meta">${esc(m.basis)} · ${esc(m.tradeDate||time(m.endAt))}${m.stale?' · 최신 자료 아님':''}</p><div class="cf-market-grid">${Object.entries(m.windows||{}).map(([label,v])=>`<div><span>${label}</span><strong class="${v?.returnPct>0?'positive':v?.returnPct<0?'negative':''}">${num(v?.returnPct,'%',true)}</strong><small>시장 대비 ${num(v?.excessReturn,'%p',true)}</small></div>`).join('')}</div><p class="cf-meta">비교: ${esc(m.benchmark)} · 출처 ${esc(m.source)}</p><details><summary>거래량·자료 기준</summary><p>상대 거래량 ${num(Object.values(m.windows)[0]?.relativeVolume,'배')} · 수익률 Z-score ${num(Object.values(m.windows)[0]?.returnZScore)}</p><p>기간 ${esc(time(m.startAt))} → ${esc(time(m.endAt))}<br>수집 ${esc(time(m.receivedAt))}</p>${m.nextKoreanSession?`<p>다음 한국 거래일 ${esc(m.nextKoreanSession.date)}</p>`:''}</details></section>`;}
export function identityLabel(a){
 if(a.kind==='CRYPTO')return [labels[a.kind],a.chain||'체인 확인 중',a.contractAddress||(a.canonicalIdentity?.complete?'네이티브 코인':'계약 주소 확인 중')].join(' · ');
 return [labels[a.kind],a.exchange||(a.kind==='US_STOCK'?'거래소 확인 중':a.market),a.issuerId?(a.kind==='KR_STOCK'?'corp_code ':'CIK ')+a.issuerId:'발행인 확인 중'].filter(Boolean).join(' · ');
}
export function resultMarkup(run){
 if(run.state==='selection_required')return `<section class="surface cf-empty"><h2>분석할 자산을 선택해 주세요</h2><p>${esc(run.message)}</p><div class="cf-choices">${(run.choices||[]).map(a=>`<button type="button" data-cf-choice="${esc(a.id)}">${esc(a.name)} · ${esc(a.symbol)} <small>${esc(identityLabel(a))}</small></button>`).join('')}</div></section>`;
 if(['queued','running'].includes(run.state))return `<section class="surface cf-progress" role="status"><span class="cf-badge">${esc(labels[run.intent])}</span><h2>${esc(labels[run.stage]||'자료 확인 중')}</h2><p>확인한 원문과 실제 수치만 사용합니다.</p><ol>${['identity','market','evidence','analyzing','validating'].map(s=>`<li class="${run.stage===s?'active':''}">${esc(labels[s])}</li>`).join('')}</ol></section>`;
 const passed=(run.candidates||[]).filter(c=>c.gate.passed),pending=(run.candidates||[]).filter(c=>!c.gate.passed),facts=(run.claims||[]).filter(c=>['VERIFIED','SUPPORTED'].includes(c.status)),unchecked=(run.claims||[]).filter(c=>!['VERIFIED','SUPPORTED'].includes(c.status));
 return `<section class="surface cf-answer"><div class="cf-meta"><span class="cf-badge">${esc(labels[run.intent])}</span>${run.asset?`<span>${esc(run.asset.name)} · ${esc(run.asset.symbol)}</span>`:''}<span>${run.cached?'저장된 분석 · ':''}${esc(time(run.cacheAsOf||run.completedAt))}</span></div><h2>${esc(run.message||'분석 결과')}</h2>${run.classification?.scenario?'<p>아래 자료는 조건부 경로를 살펴보기 위한 근거입니다.</p>':''}${run.causality?`<p>촉매 신뢰도: ${esc(labels[run.causality.confidence])}</p>`:''}${run.state==='failed'||run.state==='no_result'?'<button class="secondary-button" type="button" data-cf-retry>다시 확인</button>':''}</section>${marketMarkup(run.market)}${facts.length?`<section class="surface cf-evidence"><h2>원문에서 확인한 사실</h2>${facts.map(claimMarkup).join('')}</section>`:''}${passed.length?`<section class="cf-results"><h2>영향 경로가 확인된 자산 <small>${passed.length}</small></h2>${passed.map(c=>candidateMarkup(c,run.claims||[])).join('')}</section>`:''}${pending.length?`<details class="surface cf-pending"><summary>추가 검증이 필요한 경로 ${pending.length}개</summary><p>관찰 후보로 확정하지 않은 자료입니다.</p>${pending.map(c=>candidateMarkup(c,run.claims||[])).join('')}</details>`:''}${unchecked.length?`<details class="surface cf-evidence"><summary>미확인·추론·충돌 자료 ${unchecked.length}건</summary>${unchecked.map(claimMarkup).join('')}</details>`:''}${run.cryptoMetadata?`<details class="surface cf-extra"><summary>프로토콜·토큰 구조</summary><div class="cf-two"><div><h3>프로토콜</h3><p>TVL ${num(run.cryptoMetadata.protocolFundamentals?.tvl,' USD')}</p><p>수익·수수료: 공식 근거 확인 필요</p></div><div><h3>토큰</h3><p>유통량 ${num(run.cryptoMetadata.tokenomics?.circulatingSupply)}</p><p>최대 공급량 ${num(run.cryptoMetadata.tokenomics?.maxSupply)}</p><p>FDV ${num(run.cryptoMetadata.tokenomics?.fdv,' USD')}</p><p>언락·보유 집중도: 미확인</p></div></div><p class="cf-meta">${external(run.cryptoMetadata.source,'CoinGecko')} · ${esc(time(run.cryptoMetadata.asOf))}</p></details>`:''}${run.earnings?`<section class="surface cf-extra"><h2>실적 흐름</h2><p>${esc(run.earnings.note)}</p><a href="${esc(run.earnings.href)}" data-nav>기존 분기 실적과 근거 보기 →</a></section>`:''}<details class="surface cf-extra"><summary>출처·자료 한계·처리 기록</summary>${(run.dataGaps||[]).map(s=>`<p>${esc(s)}</p>`).join('')}<ul>${(run.sources||[]).map(s=>`<li>${external(s.url,s.title||s.publisher)}<br><small>발행 ${esc(time(s.publishedAt))} · 확인 ${esc(time(s.observedAt))}</small></li>`).join('')}</ul><p>시세 ${run.diagnostics?.market||0}건 → 검색 ${run.diagnostics?.searchResults||0}건 → 원문 ${run.diagnostics?.readDocuments||0}건 → 사실 확인 ${run.diagnostics?.validatedClaims||0}건 → 후보 통과 ${run.diagnostics?.passed||0}건</p>${(run.failures||[]).map(f=>`<p class="cf-meta">${esc(f.asset||f.stage)} · ${esc(f.code)}</p>`).join('')}<p class="cf-meta">${esc(run.version)} · ${esc(run.promptVersion)} · ${esc(run.model)}</p></details>`;
}
function mountLegacyCatalyst(root){
 let dead=false,pollTimer,searchTimer,searchVersion=0,currentAsset=null,busy=false,currentRun=null;const abort=new AbortController();
 root.innerHTML=`<div class="cf-shell"><div class="page-heading"><div><div class="eyebrow">CATALYST & IMPACT FINDER</div><h1>촉매 분석</h1><p>사건과 자산을 연결하는 근거를 찾아보세요.</p></div></div><form class="surface cf-form"><label for="cf-question">어떤 변화가 궁금하세요?</label><div class="cf-query"><textarea id="cf-question" rows="2" maxlength="500" required minlength="3" placeholder="예: MU 주가가 오른 이유는?"></textarea><button class="primary-button" type="submit">분석하기 →</button></div><div class="cf-examples">${examples.map(q=>`<button type="button" data-cf-example="${esc(q)}">${esc(q)}</button>`).join('')}</div><details class="cf-options"><summary>자산 선택·근거 주소·심화 분석</summary><label for="cf-asset">분석할 주식·코인</label><input id="cf-asset" type="search" autocomplete="off" placeholder="종목명 또는 티커" aria-controls="cf-assets"><div id="cf-assets" class="cf-choices"></div><p id="cf-selected" class="cf-meta"></p><label for="cf-sources">원문 주소 (선택 · 최대 3개)</label><textarea id="cf-sources" rows="2" placeholder="https://… (한 줄에 하나)"></textarea><label class="cf-check"><input type="checkbox" id="cf-deep"> 심화 분석 · 처리 시간과 AI 사용량이 늘어날 수 있습니다</label></details><p id="cf-error" class="cf-warning" role="alert"></p></form><div id="cf-output" aria-live="polite"></div><details id="cf-history" class="surface cf-extra"><summary>내 최근 분석</summary><div></div></details><div id="cf-admin"></div></div>`;
 const $=s=>root.querySelector(s),request=async(url,opts={})=>{const r=await fetch(url,{...opts,signal:abort.signal});const data=await r.json();if(!r.ok)throw Error(data.message||'연결을 확인해 주세요.');return data;};
 const setBusy=v=>{busy=v;$('.cf-query button').disabled=v;$('.cf-query button').textContent=v?'분석 중…':'분석하기 →';};
 const render=run=>{if(dead)return;currentRun=run;$('#cf-output').innerHTML=resultMarkup(run);};
 async function history(){try{const r=await request('/api/catalyst/runs');if(!dead)$('#cf-history>div').innerHTML=r.items.map(r=>`<button type="button" data-cf-run="${esc(r.id)}">${esc(r.query)} <small>${esc(time(r.createdAt))}</small></button>`).join('')||'<p>아직 분석 기록이 없습니다.</p>';}catch{}}
 async function poll(id){try{const run=await request('/api/catalyst/runs/'+id);render(run);if(['running','queued'].includes(run.state))pollTimer=setTimeout(()=>poll(id),1800);else{setBusy(false);void history();}}catch(e){if(dead)return;$('#cf-error').textContent=e.message;setBusy(false);}}
 async function submit(){if(busy)return;$('#cf-error').textContent='';setBusy(true);try{const query=$('#cf-question').value.trim(),run=await request('/api/catalyst/runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query,assetId:currentAsset?.id,sourceUrls:$('#cf-sources').value.split('\n').map(x=>x.trim()).filter(Boolean),deep:$('#cf-deep').checked})});render(run);if(run.id){const u=new URL(location.href);u.searchParams.set('run',run.id);window.history.replaceState({},'',u);pollTimer=setTimeout(()=>poll(run.id),600);}else setBusy(false);}catch(e){if(dead)return;$('#cf-error').textContent=e.message;setBusy(false);}}
 root.querySelector('form').addEventListener('submit',e=>{e.preventDefault();void submit();},{signal:abort.signal});
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.cfExample){$('#cf-question').value=b.dataset.cfExample;currentAsset=null;$('#cf-selected').textContent='';$('#cf-question').focus();}else if(b.dataset.cfChoice){currentAsset={id:b.dataset.cfChoice};$('#cf-selected').textContent=b.textContent.trim();$('#cf-assets').innerHTML='';if(currentRun?.state==='selection_required')void submit();}else if(b.dataset.cfRun){clearTimeout(pollTimer);setBusy(true);void poll(b.dataset.cfRun);}else if(b.hasAttribute('data-cf-retry'))void submit();else if(b.hasAttribute('data-cf-usage'))void admin();},{signal:abort.signal});
 $('#cf-asset').addEventListener('input',()=>{clearTimeout(searchTimer);currentAsset=null;const version=++searchVersion;searchTimer=setTimeout(async()=>{try{const d=await request('/api/catalyst/assets?q='+encodeURIComponent($('#cf-asset').value));if(dead||version!==searchVersion)return;$('#cf-assets').innerHTML=d.items.map(a=>`<button type="button" data-cf-choice="${esc(a.id)}">${esc(a.name)} · ${esc(a.symbol)} <small>${esc(identityLabel(a))}</small></button>`).join('');}catch{}},250);},{signal:abort.signal});
 async function admin(){try{const d=await request('/api/catalyst/usage');if(!dead)$('#cf-admin').innerHTML=`<details class="surface cf-extra"><summary>관리자 · 오늘 AI 사용량</summary><p>${esc(d.scope)}</p><p>집계 ${num(d.actualTokens)} tokens · 캐시 입력 ${num(d.cachedInputTokens)} · 예약 포함 ${num(d.budget.used)} / ${num(d.budget.hard)}</p><p>분석 ${d.queries}회 · 호출 ${d.calls}회 · 캐시 ${d.cacheHits}회 · 실패 ${d.failures}회 · 429 ${d.rateLimited}회</p><p>평균 ${num(d.averageTokens)} tokens / 질문 · 전체 처리 P95 ${num(d.p95Latency===null?null:d.p95Latency/1000)}초</p><button type="button" class="secondary-button" data-cf-usage>새로고침</button></details>`;}catch{}}
 void request('/api/catalyst/config').then(c=>{if(dead)return;if(!c.ready)$('#cf-error').textContent='서버 API 키 또는 분석 작업자 설정을 확인해 주세요.';if(c.admin)void admin();}).catch(e=>{if(!dead)$('#cf-error').textContent=e.message;});
 const q=new URLSearchParams(location.search);$('#cf-question').value=q.get('q')||'';if(q.get('asset')){currentAsset={id:q.get('asset')};$('#cf-selected').textContent='선택된 자산: '+q.get('asset');}if(q.get('run')){setBusy(true);void poll(q.get('run'));}void history();
 return {destroy(){dead=true;abort.abort();clearTimeout(pollTimer);clearTimeout(searchTimer);}};
}

export function mountCatalyst(root){
 const p=new URLSearchParams(location.search);if(p.has('theses')||p.has('thesis')||p.has('thesisDraft'))return mountTheses(root);if(p.has('run')||p.has('legacy'))return mountLegacyCatalyst(root);
 if(p.has('classic')||p.has('analysis'))return mountResearchDelivery(root);
 let dead=false,view;root.innerHTML='<p role="status">리서치를 열고 있습니다.</p>';
 fetch('/api/catalyst/config').then(r=>r.json()).then(c=>{if(!dead)view=c.freeResearch===false?mountResearchDelivery(root):mountFreeResearch(root);}).catch(()=>{if(!dead)view=mountFreeResearch(root);});
 return {destroy(){dead=true;view?.destroy();}};
}
